import base64, hashlib, importlib, json, os, pathlib, platform, resource, sys, tempfile, time, unittest, zlib
EXPECTED = {'grouped_work_profile_v1.py': 'fbeae97349126a9dc805853e02b9c16a207e14e572fb5d0efe39ac9b25e4aca5', 'grouped_work_composition_v1.py': '0210e710f83e9c8c58af7f362521b49024bca28917a7a2a3793d57669b19843b', 'test_grouped_work_profile_v1.py': '3b3faa1aad2edf8a3f17574f29d177678ce44521486837521700bdec2848f639', 'test_grouped_work_composition_v1.py': '560a0fbc0716dec003328604bcd54a796d5739b69c139e99b98d91c6b438021d'}
PACKED = ''
PACKED_SHA256 = 'cc6362c0d21c23cfca5056d8f34221d5f5681c241063b62ded804be7b09c2677'
started = time.monotonic()
encoded = base64.b64decode(PACKED, validate=True)
assert hashlib.sha256(encoded).hexdigest() == PACKED_SHA256, 'payload digest mismatch'
decoded = json.loads(zlib.decompress(encoded))
assert set(decoded) == set(EXPECTED), 'unexpected payload file inventory'
artifact_root = pathlib.Path.cwd()
report_path = artifact_root / 'profile-composition-report.json'
if report_path.exists():
    raise RuntimeError('report destination already exists')
runtime = {'python': sys.version, 'executable': sys.executable, 'platform': platform.platform(),
           'machine': platform.machine(), 'logical_cpu_count': os.cpu_count(),
           'requested_accelerator': 'NONE', 'requested_shape': 'STANDARD'}
try:
    runtime['cpu_model_names'] = sorted(set(line.split(':', 1)[1].strip() for line in pathlib.Path('/proc/cpuinfo').read_text().splitlines() if line.startswith('model name')))
    runtime['memory_total_kib'] = int(next(line.split()[1] for line in pathlib.Path('/proc/meminfo').read_text().splitlines() if line.startswith('MemTotal:')))
except (OSError, StopIteration, ValueError, IndexError):
    runtime['hardware_readback_incomplete'] = True
def usage(which):
    value = resource.getrusage(which)
    return {'user_cpu_seconds': value.ru_utime, 'system_cpu_seconds': value.ru_stime, 'maximum_rss_kib': value.ru_maxrss}
before_usage = {'self': usage(resource.RUSAGE_SELF), 'children': usage(resource.RUSAGE_CHILDREN)}
def test_ids(suite):
    for value in suite:
        if isinstance(value, unittest.TestSuite):
            yield from test_ids(value)
        else:
            yield value.id()
with tempfile.TemporaryDirectory(prefix='pon-profile-closure-89df-') as temporary:
    source = pathlib.Path(temporary)
    for name, content in decoded.items():
        raw = content.encode('utf-8')
        assert hashlib.sha256(raw).hexdigest() == EXPECTED[name], 'source digest mismatch: ' + name
        with (source / name).open('xb') as stream:
            stream.write(raw)
        (source / name).chmod(0o400)
    def source_state():
        return {name: {'sha256': hashlib.sha256((source / name).read_bytes()).hexdigest(), 'size_bytes': (source / name).stat().st_size} for name in sorted(EXPECTED)}
    source_before = source_state()
    sys.path.insert(0, str(source))
    suite = unittest.TestSuite()
    inventory = []
    for module_name, expected_count in [('test_grouped_work_profile_v1', 45), ('test_grouped_work_composition_v1', 37)]:
        module = importlib.import_module(module_name)
        assert pathlib.Path(module.__file__).parent == source, 'unexpected module origin'
        tests = unittest.defaultTestLoader.loadTestsFromModule(module)
        ids = list(test_ids(tests))
        assert len(ids) == expected_count, 'unexpected test inventory'
        inventory.append({'module': module_name, 'expected_count': expected_count, 'test_ids': ids})
        suite.addTests(tests)
    assert suite.countTestCases() == 82
    print('PON_COLAB_CONTROLLED_SOURCE ' + json.dumps({'sources': source_before, 'runtime': runtime}, sort_keys=True), flush=True)
    tests_started = time.monotonic()
    result = unittest.TextTestRunner(stream=sys.stdout, verbosity=2).run(suite)
    test_wall = time.monotonic() - tests_started
    source_after = source_state()
    passed = (result.wasSuccessful() and not result.skipped and not result.expectedFailures
              and not result.unexpectedSuccesses and result.testsRun == 82 and source_before == source_after)
    report = {
        'schema': 'pon-profile-composition-colab-controlled-tests-v1',
        'evidence_kind': 'CONTROLLED_FIXTURE',
        'scope': 'SUPPLEMENTARY_PURE_PYTHON_PROFILE_AND_COMPOSITION_TESTS',
        'task_key': 'pon-profile-closure-89df-python-20261107-v1',
        'result': 'PASS' if passed else 'FAIL', 'expected_tests': 82,
        'tests_run': result.testsRun, 'failures': len(result.failures), 'errors': len(result.errors),
        'skipped': len(result.skipped), 'expected_failures': len(result.expectedFailures),
        'unexpected_successes': len(result.unexpectedSuccesses),
        'test_inventory': inventory, 'source_before': source_before, 'source_after': source_after,
        'source_unchanged': source_before == source_after, 'runtime': runtime,
        'test_wall_seconds': test_wall, 'payload_wall_seconds': time.monotonic() - started,
        'process_usage_before': before_usage,
        'process_usage_after': {'self': usage(resource.RUSAGE_SELF), 'children': usage(resource.RUSAGE_CHILDREN)},
        'usage_scope': 'UNAUTHENTICATED_PROCESS_COUNTERS_NOT_FULL_PREPARATION_OR_HOST_NETWORK_COST',
        'preparation_and_failed_attempt_cost': 'UNKNOWN', 'provider_settled_cost': 'UNKNOWN',
        'native_rust_tests_executed': False, 'combined_33_gate_qualification': False,
        'full_workspace_or_runtime_91_qualification': False,
        'external_customer_demand_proven': False, 'external_budget_proven': False,
        'target_authorization_proven': False, 'current_external_consumer_use_proven': False,
        'independent_issuer_proven': False, 'physical_meter_proven': False,
        'complete_cost_transfer_proven': False, 'native_consensus_profile_registered': False,
        'new_ticket_requires_new_neural_computation': False, 'chainwork_weight': 0,
    }
    raw_report = (json.dumps(report, sort_keys=True, separators=(',', ':')) + '\n').encode()
    with report_path.open('xb') as stream:
        stream.write(raw_report)
    print('PON_COLAB_CONTROLLED_RESULT ' + json.dumps({key: report[key] for key in ('schema', 'evidence_kind', 'result', 'tests_run', 'failures', 'errors', 'skipped', 'source_unchanged', 'chainwork_weight')}, sort_keys=True), flush=True)
    print('PON_COLAB_REPORT_SHA256 ' + hashlib.sha256(raw_report).hexdigest(), flush=True)
    sys.path.remove(str(source))
raise SystemExit(0 if passed else 1)
